// Экран «Хранилище»: сколько файлов в папке со всеми вложенными.
func fileCount(in root: Folder) -> Int {
    var count = 0
    var stack = [root]
    while let folder = stack.popLast() {
        count += folder.files.count
        stack.append(contentsOf: folder.subfolders)
    }
    return count
}
let raw = Folder(name: "RAW", files: [900, 700], subfolders: [])
let trips = Folder(name: "Поездки", files: [300], subfolders: [raw])
let docs = Folder(name: "Документы", files: [50], subfolders: [])
let home = Folder(name: "Дом", files: [10], subfolders: [trips, docs])
print(fileCount(in: home))

key:
func fileCount(in folder: Folder) -> Int {
    var count = folder.files.count
    for sub in folder.subfolders {
        count += fileCount(in: sub)
    }
    return count
}
print(fileCount(in: home))

5

Дом 1 + Поездки 1 + RAW 2 + Документы 1 = 5. Схема как у totalSize: свои файлы плюс результат той же функции на каждой подпапке. База — папка без подпапок: цикл пустой, новых вызовов нет. Массив stack больше не нужен: непройденные папки «помнит» стек вызовов — каждый вызов на паузе стоит в своём цикле for и продолжит его, когда вложенный вызов вернётся.

