struct Folder {
    let name: String
    let files: [Int]
    let subfolders: [Folder]
}
// По памяти, без урока:
// 1) countdown(_:) — печатает «до n» по пути вглубь, «старт»
//    на дне и «после n» на обратном пути;
// 2) totalSize(of:) -> Int — размер папки со всеми вложенными.

key:
func countdown(_ n: Int) {
    if n <= 0 {
        print("старт")
        return
    }
    print("до \(n)")
    countdown(n - 1)
    print("после \(n)")
}
func totalSize(of folder: Folder) -> Int {
    var sum = folder.files.reduce(0, +)
    for sub in folder.subfolders {
        sum += totalSize(of: sub)
    }
    return sum
}

В обеих функциях есть база и шаг к ней. В `countdown` база — `n <= 0`, шаг — `n - 1`; печать до вызова идёт вглубь, после — обратно. В `totalSize` база — папка без подпапок, шаг — вызов на каждой подпапке.
